DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `final_price`(base DECIMAL(12, 2), discount DECIMAL(5, 4)) RETURNS decimal(12,2)
    DETERMINISTIC
    COMMENT 'A price after a discount (0.1 = 10 %).'
BEGIN
    RETURN ROUND(base * (1 - discount), 2);
END ;;
